request.query:
query ProductPublishState($id: ID!) {
          product(id: $id) { id title status resourcePublicationsCount { count } }
        }

mutation ActivateProduct($product: ProductUpdateInput!) {
          productUpdate(product: $product) {
            product { id }
            userErrors { field message }
          }
        }

mutation DeleteMetafields($metafields: [MetafieldIdentifierInput!]!) {
      metafieldsDelete(metafields: $metafields) {
        deletedMetafields { key }
        userErrors { field message }
      }
    }

mutation PublishToOnlineStore($id: ID!, $input: [PublicationInput!]!) {
            publishablePublish(id: $id, input: $input) {
              publishable { ... on Product { id } }
              userErrors { field message }
            }
          }
